import { DottedName } from 'modele-social'
import { PublicodesExpression } from 'publicodes'

import { ImmutableType } from '@/types/utils'
import { objectTransform, omit } from '@/utils'

import { SimulationConfig } from './SimulationConfig'
import { Situation } from './Situation'

export function updateSituation(
	config: ImmutableType<SimulationConfig>,
	currentSituation: Situation,
	dottedName: DottedName,
	value: PublicodesExpression | undefined
): Situation {
	if (value === undefined) {
		return omit(currentSituation, dottedName)
	}

	const objectifsExclusifs = config['objectifs exclusifs'] ?? []

	if (!objectifsExclusifs.includes(dottedName)) {
		return { ...currentSituation, [dottedName]: value }
	}

	const objectifsToReset = objectifsExclusifs.filter(
		(name) => name !== dottedName
	)

	const clearedSituation = objectTransform(currentSituation, (entries) =>
		entries.filter(
			([dottedName]) => !objectifsToReset.includes(dottedName as DottedName)
		)
	)

	return { ...clearedSituation, [dottedName]: value }
}
import { pipe } from 'effect'
import { headNonEmpty, NonEmptyArray, of } from 'effect/Array'
import { isUndefined } from 'effect/Predicate'
import {
	filter,
	fromEntries,
	isEmptyRecord,
	keys,
	partition,
	size,
	toEntries,
} from 'effect/Record'
import { DottedName } from 'modele-social'
import { PublicodesExpression } from 'publicodes'

import { SimulationConfig } from '@/domaine/SimulationConfig'
import { Situation } from '@/domaine/Situation'
import { omit } from '@/utils'

export function updateSituationMulti(
	config: SimulationConfig,
	currentSituation: Situation,
	amendement: Record<DottedName, PublicodesExpression | undefined>
): Situation {
	const [àAjuster, àEffacer] = partition(amendement, isUndefined) as [
		Record<DottedName, PublicodesExpression>,
		Record<DottedName, undefined>,
	]
	const objectifsExclusifs = config['objectifs exclusifs'] ?? []
	const estUnObjectifExclusif = (règle: DottedName): boolean =>
		objectifsExclusifs.includes(règle)

	const [règlesNormales, règlesExclusives] = partition(
		àAjuster,
		(valeur, règle) => estUnObjectifExclusif(règle)
	)

	const clearedSituation = size(règlesExclusives)
		? filter(
				currentSituation as Record<DottedName, PublicodesExpression>,
				(_, règle) => règle in règlesExclusives
		  )
		: currentSituation

	return omit(
		{
			...clearedSituation,
			...keepFirstEntry(règlesExclusives),
			...règlesNormales,
		},
		...keys(àEffacer)
	)
}

const keepFirstEntry = <T, K extends string>(
	record: Record<K, T>
): Record<K, T> =>
	isEmptyRecord(record)
		? ({} as Record<K, T>)
		: (pipe(
				toEntries(record) as NonEmptyArray<[K, T]>,
				headNonEmpty,
				of,
				fromEntries
		  ) as Record<K, T>)
import { pipe } from 'effect'
import { isString } from 'effect/Predicate'
import * as R from 'effect/Record'
import { DottedName } from 'modele-social'
import { PublicodesExpression } from 'publicodes'

import { SimulationConfig } from '@/domaine/SimulationConfig'
import { Situation } from '@/domaine/Situation'
import { ImmutableType } from '@/types/utils'

export function updateSituationMultiple(
	config: ImmutableType<SimulationConfig>,
	currentSituation: Situation,
	préfixe: DottedName,
	valeurs: Record<string, PublicodesExpression>
): Situation {
	const nouvellesValeurs = pipe(
		valeurs,
		R.mapKeys((suffixe) => `${préfixe} . ${suffixe}`),
		R.map((valeur) => (isString(valeur) ? `'${valeur}'` : valeur)) // 😭
	)

	return { ...currentSituation, ...nouvellesValeurs }
}

